Hier is precies wat je in `OPD-5/Core/Src/main.c` moet aanpassen.

1) Voeg een drempelwaarde toe bij `/* USER CODE BEGIN PD */`:

```c
/* USER CODE BEGIN PD */
#define ADC_THRESHOLD_X 2000U
/* USER CODE END PD */
```

2) Initialiseer `PB10` als output in `MX_GPIO_Init()` (USER CODE zodat CubeMX het niet overschrijft):

```c
/* USER CODE BEGIN MX_GPIO_Init_2 */
GPIO_InitStruct.Pin = GPIO_PIN_10;
GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_PP;
GPIO_InitStruct.Pull = GPIO_NOPULL;
GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
HAL_GPIO_Init(GPIOB, &GPIO_InitStruct);

/* LED initieel uit */
HAL_GPIO_WritePin(GPIOB, GPIO_PIN_10, GPIO_PIN_RESET);
/* USER CODE END MX_GPIO_Init_2 */
```

3) Stuur de LED in je `while(1)` op basis van de potentiometerwaarde:

```c
while (1)
{
  waarde = Read_ADC1_Value();

  if (waarde > ADC_THRESHOLD_X)
  {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_10, GPIO_PIN_SET);
  }
  else
  {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_10, GPIO_PIN_RESET);
  }

  int len = snprintf(txBuffer, sizeof(txBuffer), "ADC1_IN9: %lu\r\n", waarde);
  HAL_UART_Transmit(&huart2, (uint8_t*)txBuffer, len, HAL_MAX_DELAY);

  HAL_Delay(200);
}
```

